changeSet.sql:
CREATE TABLE profiles ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email VARCHAR(255) NOT NULL UNIQUE, first_name VARCHAR(255), last_name VARCHAR(255) );
CREATE TABLE chat ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, title VARCHAR(255) NOT NULL, profile_id UUID NOT NULL CONSTRAINT profiles_foreign_key REFERENCES profiles(id) ON DELETE CASCADE );
CREATE TABLE chat_message ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), message_type VARCHAR(127) NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, chat_id UUID NOT NULL CONSTRAINT chat_foreign_key REFERENCES chat(id) ON DELETE CASCADE );
CREATE INDEX chat_message_chat_created_idx ON chat_message (chat_id, created_at);
CREATE INDEX chat_profile_created_idx ON chat (profile_id, created_at DESC);
CREATE TABLE loaded_document ( id BIGSERIAL PRIMARY KEY, filename VARCHAR(255) NOT NULL, content_hash VARCHAR(64) NOT NULL, document_type VARCHAR(10) NOT NULL, chunk_count INTEGER, loaded_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT unique_document UNIQUE (filename, content_hash) );
CREATE INDEX idx_loaded_documents_filename ON loaded_document(filename);
CREATE TABLE vector_store ( id VARCHAR(255) PRIMARY KEY, content TEXT, metadata JSON, embedding VECTOR(1024) );
CREATE INDEX vector_store_hnsw_index ON vector_store USING hnsw (embedding vector_cosine_ops);

changeSet.rollback:
DROP TABLE IF EXISTS vector_store;
DROP TABLE IF EXISTS loaded_document;
DROP TABLE IF EXISTS chat_message;
DROP TABLE IF EXISTS chat;
DROP TABLE IF EXISTS profiles;
